{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Codeine, the closest structural analogue sharing the methoxy-morphinan scaffold, has an absolute oral bioavailability of 40 ± 22% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethylmorphine, a close N-ethyl analogue, has a minimum systemic availability of 0.74 (range 0.54–0.92) in healthy subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Morphine, the phenolic analogue, showed a mean absolute oral bioavailability of 29.2% in healthy volunteers under fasted conditions, directly supporting F ≥ 20% for this morphinan family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Immediate-release morphine had an absolute oral bioavailability of 23.8 ± 4.9%, still above the 20% threshold despite extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine, a related opium alkaloid with a similar ether-containing polycyclic scaffold, has an absolute oral bioavailability of 30%, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a codeine-type morphinan (neopine isomer). All close analogues—codeine, ethylmorphine, morphine, diamorphine, and noscapine—have measured oral bioavailability at or above 20%, with most well above. Physicochemical properties are favorable, so F ≥ 20% is supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for neopine itself.",
    "Stereochemical differences from codeine could alter first-pass metabolism, though the functional groups and scaffold are highly similar.",
    "Fasted-state data are directly available only for morphine, not for the exact query isomer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

